  const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const f = (n,d=4) => Number.isFinite(n)?n.toLocaleString('es-CL',{maximumFractionDigits:d}):'no definido';
  const copy = x => structuredClone(x);
  let tab = 'reg', regCase = 'intro', chiCase = 'tp', tariff = 0;
  let points=copy(D.intro), observed=copy(D.tp), arrivals=copy(D.arrivals), tariffs=copy(D.tariffs);
  let xLabel='X',yLabel='Y',predict=10,alpha=.05,params={h:5,t:10,target:80,occ:100,shrink:0};
  let graphType='scatter', showTrend=true, formulaOn=false, formula='=2*X+5';
