      const s=saved.state, d=snapshot();
      const matrix=(a,cols,max)=>Array.isArray(a)&&a.length>=2&&a.length<=max&&a.every(r=>Array.isArray(r)&&r.length===cols&&r.every(v=>typeof v==='number'||typeof v==='string'));
      if(s&&['reg','chi','erlang','lookup'].includes(s.tab)&&['intro','health','countries','gaseosas','cigarrillos'].includes(s.regCase)&&['tp','tpSaved','abc','health'].includes(s.chiCase)&&['scatter','line','bar'].includes(s.graphType)&&matrix(s.points,2,1000)&&matrix(s.observed,3,3)&&Array.isArray(s.arrivals)&&s.arrivals.length===9&&Array.isArray(s.tariffs)&&s.tariffs.length===D.tariffs.length&&s.tariffs.every(r=>Array.isArray(r)&&r.length===5)&&Number.isInteger(s.tariff)&&s.tariff>=0&&s.tariff<s.tariffs.length&&['xLabel','yLabel','formula'].every(k=>typeof s[k]==='string'&&s[k].length<=300)&&['params','generator','scratch'].every(k=>s[k]&&Object.keys(d[k]).every(key=>typeof s[k][key]==='number'||typeof s[k][key]==='string'))&&Number.isInteger(s.chiCell)&&s.chiCell>=0&&s.chiCell<s.observed.length*3){restore({...d,...s});message='Práctica guardada recuperada.';}
